contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: we take an amount to deposit first, then attempt withdraw
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");

        // Record before-values
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeMyBalance = c.balances(address(this));

        // Deposit into c from this contract
        c.deposit{value: depositAmount}();

        uint256 afterDepositContractBalance = address(c).balance;
        uint256 afterDepositMyBalance = c.balances(address(this));

        // deposit must have increased both observables consistently
        // (we do not assert here; we only use values later)

        // Attempt withdraw and record whether it reverted
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 finalContractBalance = address(c).balance;
        uint256 finalMyBalance = c.balances(address(this));

        // General rule asserted: if withdraw succeeded (not reverted) then
        // 1) the mapping balance for this address decreased by exactly withdrawAmount
        // 2) the contract's Ether balance decreased by at least withdrawAmount
        // If withdraw reverted, no condition on balances is required here.
        assert(reverted || (afterDepositMyBalance >= withdrawAmount &&
               afterDepositMyBalance - finalMyBalance == withdrawAmount &&
               afterDepositContractBalance - finalContractBalance >= withdrawAmount));
    }

    // Allow receiving Ether so that this contract can fund deposits/withdraws
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take depositAmount to fund a deposit, and withdrawAmount to attempt a withdraw.
    // The test contract must have enough balance to perform the deposit.
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");

        // Record contract Ether balance before deposit
        uint256 beforeContractBalance = address(c).balance;

        // Deposit into c from this contract
        c.deposit{value: depositAmount}();

        // Record contract Ether balance after deposit and before withdraw
        uint256 afterDepositContractBalance = address(c).balance;

        // Attempt withdraw and record whether it reverted
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record contract Ether balance after withdraw attempt
        uint256 afterWithdrawContractBalance = address(c).balance;

        // General rule: if withdraw did not revert then the contract's Ether balance must have decreased by at least withdrawAmount
        // (we compare afterDepositContractBalance - afterWithdrawContractBalance >= withdrawAmount, but avoid underflow by branching in the assert expression)
        assert(reverted || (afterDepositContractBalance >= afterWithdrawContractBalance && (afterDepositContractBalance - afterWithdrawContractBalance) >= withdrawAmount));
    }

    // allow receiving Ether
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will optionally deposit some Ether into c, then call refund() and check the relation
    // between balances observable via address(c).balance and the stored per-address balance for this contract.
    function run(uint256 depositAmount) public payable {
        // ensure this test contract has funds to deposit if depositAmount > 0
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Observe per-address recorded balance for this contract before any actions
        uint256 beforeRecorded = c.balances(address(this));
        // Observe contract Ether balance before
        uint256 beforeContract = address(c).balance;

        // If requested, deposit to increase both recorded and contract balances
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // Observe values just before refund
        uint256 recordedBeforeRefund = c.balances(address(this));
        uint256 contractBeforeRefund = address(c).balance;

        // Attempt refund and record whether it reverted
        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }

        // Observe after-state (only meaningful if call succeeded)
        uint256 recordedAfter = c.balances(address(this));
        uint256 contractAfter = address(c).balance;

        // General invariant: if refund did not revert, then the recorded balance for this address must become zero,
        // and the contract's Ether balance must have decreased by at least the decrease in the recorded balance
        // (i.e., contractBeforeRefund - contractAfter >= recordedBeforeRefund - recordedAfter).
        // If refund reverted, we make no claims about state change.
        assert(refundedReverted || (recordedAfter == 0 &&
               contractBeforeRefund >= contractAfter &&
               // avoid underflow by using >= checks before subtraction; express inequality without subtracting when possible
               (contractBeforeRefund - contractAfter) >= (recordedBeforeRefund - recordedAfter)));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We optionally deposit some Ether into c, then call refund() and check that if refund succeeds,
    // the contract's balance decreases by at least the Ether our test contract receives from the call.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Record balances before any action
        uint256 beforeThis = address(this).balance;
        uint256 beforeC = address(c).balance;

        // Optionally deposit into c
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // Attempt refund and record success/failure and balances after
        bool refundedReverted;
        uint256 afterThis;
        uint256 afterC;
        try c.refund() {
            refundedReverted = false;
            afterThis = address(this).balance;
            afterC = address(c).balance;
        } catch {
            refundedReverted = true;
            // fill with current balances so variables are defined; these won't be used when reverted
            afterThis = address(this).balance;
            afterC = address(c).balance;
        }

        // If refund did not revert, then the decrease in c's balance is at least the increase in this contract's balance
        assert(refundedReverted || (beforeC >= afterC && afterThis >= beforeThis && (beforeC - afterC) >= (afterThis - beforeThis)));
    }

    receive() external payable { }
}

