}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: we take params to drive deposit/withdraw/refund/migrate
    function run(address to, uint256 depAmt, uint256 wdrAmt, bool doDeposit, bool doWithdraw, bool doRefund, bool doMigrate) public payable {
        require(address(this).balance >= depAmt);

        // observe before-values
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeMyBalance = c.balances(address(this));

        // perform chosen sequence of calls (each state-changing call must be a top-level statement)
        bool depReverted = false;
        if (doDeposit) {
            // attempt deposit with depAmt
            try c.deposit{value: depAmt}() {
                depReverted = false;
            } catch {
                depReverted = true;
            }
        }

        bool wdrReverted = false;
        if (doWithdraw) {
            try c.withdraw(wdrAmt) {
                wdrReverted = false;
            } catch {
                wdrReverted = true;
            }
        }

        bool refundReverted = false;
        if (doRefund) {
            try c.refund() {
                refundReverted = false;
            } catch {
                refundReverted = true;
            }
        }

        bool migrateReverted = false;
        if (doMigrate) {
            // migrateTo can only be called by creator; here it will likely revert. Still we catch.
            try c.migrateTo(to) {
                migrateReverted = false;
            } catch {
                migrateReverted = true;
            }
        }

        // observe after-values
        uint256 afterContractBalance = address(c).balance;
        uint256 afterMyBalance = c.balances(address(this));

        // Compute net change according to public observed per-address balance
        // Note: when withdraw or refund succeeded, Ether was sent to this contract increasing address(this).balance,
        // and c's balance decreased accordingly. Deposit on success increases both c.balance and c.balances(this).
        // The invariant: (contract balance) + (per-address reported balance for this test contract) changes only by
        // the net effect of successful deposits (increase by amount) minus successful transfers out (decrease by amount).

        // We don't know exact amounts transferred out by withdraw/refund if they reverted; so form expected relation:
        // Let netObserved = afterContractBalance + afterMyBalance - (beforeContractBalance + beforeMyBalance)
        // This netObserved must equal +depAmt if deposit succeeded and no other successful outgoing transfers to this address occurred,
        // but withdraw and refund move funds from c to this test contract and also decrease c.balances; the sum should reflect those.
        // More generally, the sum of (address(c).balance + c.balances(this)) should only change due to successful deposit calls (which add msg.value to both)
        // or successful migrateTo (moves whole contract balance to 'to' address) — but migrateTo changes contract balance without affecting c.balances(this).

        // We assert the general rule: if migrateTo succeeded, then afterContractBalance == 0 (migrate sends full balance out);
        // otherwise, the quantity (address(c).balance + c.balances(this)) equals its previous value plus depAmt if and only if deposit succeeded and no successful withdraw/refund occurred.

        if (!migrateReverted) {
            // migrateTo sent all Ether out of contract
            assert(afterContractBalance == 0);
        } else {
            // If migrate did not run (or reverted), then the combined stored value should reflect only net successful deposit/withdraw/refund effects.
            // In C's logic: deposit increases both contract balance and balances[this] by depAmt on success,
            // withdraw and refund transfer Ether out and decrease balances[this] accordingly, keeping the sum (contract balance + balances[this]) unchanged for withdraw/refund when they succeed,
            // because withdraw/refund move Ether from c to msg.sender and decrement balances[msg.sender] by same amount.

            // Therefore: (afterContractBalance + afterMyBalance) == (beforeContractBalance + beforeMyBalance) + (depReverted ? 0 : depAmt)
            uint256 lhs = afterContractBalance + afterMyBalance;
            uint256 rhs = beforeContractBalance + beforeMyBalance + (depReverted ? 0 : depAmt);
            assert(lhs == rhs);
        }
    }

    // allow receiving Ether from c.withdraw / c.refund
    receive() external payable {}
}

contract InvMutTest {
