    // single public test function: take params to drive deposit/withdraw/refund/migrate
    function run(address to, uint256 depAmt, uint256 wdrAmt, bool doDeposit, bool doWithdraw, bool doRefund, bool doMigrate) public payable {
        // ensure this test contract has enough Ether to send depAmt when asked
        require(address(this).balance >= depAmt);

        // observe before-values: contract balance and this contract's Ether balance
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeMyEther = address(this).balance;

        // perform chosen sequence of calls. Each state-changing call is a top-level statement.
        bool depReverted = false;
        if (doDeposit) {
            try c.deposit{value: depAmt}() {
                depReverted = false;
            } catch {
                depReverted = true;
            }
        }

        bool wdrReverted = false;
        if (doWithdraw) {
            try c.withdraw(wdrAmt) {
                wdrReverted = false;
            } catch {
                wdrReverted = true;
            }
        }

        bool refundReverted = false;
        if (doRefund) {
            try c.refund() {
                refundReverted = false;
            } catch {
                refundReverted = true;
            }
        }

        bool migrateReverted = false;
        if (doMigrate) {
            try c.migrateTo(to) {
                migrateReverted = false;
            } catch {
                migrateReverted = true;
            }
        }

        // observe after-values
        uint256 afterContractBalance = address(c).balance;
        uint256 afterMyEther = address(this).balance;

        // The tested general rule:
        // - If migrateTo succeeded, the contract's balance must be zero afterwards.
        // - Otherwise, the change in the sum (address(c).balance + address(this).balance)
        //   equals +depAmt if and only if deposit succeeded (since withdraw/refund move Ether from c to this and
        //   decrease the internal bookkeeping balances in C so that the net sum is unchanged by successful withdraw/refund).

        if (!migrateReverted) {
            // migrateTo should move all Ether out of the contract
            assert(afterContractBalance == 0);
        } else {
            // compute observed net change in Ether between this contract and c
            // (afterContract + afterThis) - (beforeContract + beforeThis) == (depReverted ? 0 : depAmt)
            // avoid underflow by rearranging to a direct equality using addition
            uint256 lhs = afterContractBalance + afterMyEther;
            uint256 rhs = beforeContractBalance + beforeMyEther + (depReverted ? 0 : depAmt);
            assert(lhs == rhs);
        }
    }

    // allow receiving Ether from c.withdraw / c.refund / migrate
    receive() external payable {}
}

