contract InvMutTest {
    C c;
    // we record Ether we receive from c in this test to observe transfers out
    uint256 public receivedFromC;

    constructor(C _c) {
        c = _c;
        receivedFromC = 0;
    }

    // single public test function with parameters to drive c
    function run(address to, uint256 depositAmount, uint256 withdrawAmount, bool callRefund, bool callMigrate) public payable {
        // ensure we have Ether to send as deposit if requested
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount, "not enough balance for deposit");
        }

        // record balances before actions
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // perform deposit if requested
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // try withdraw (may revert if withdrawAmount > balances[msg.sender])
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // try refund if requested
        bool refundReverted = false;
        if (callRefund) {
            try c.refund() {
                refundReverted = false;
            } catch {
                refundReverted = true;
            }
        }

        // try migrate; only creator (deployer of c) can succeed — our calls should revert
        bool migrateReverted;
        if (callMigrate) {
            try c.migrateTo(to) {
                migrateReverted = false;
            } catch {
                migrateReverted = true;
            }
        } else {
            migrateReverted = true; // did not call
        }

        // We cannot read internal balances mapping, but we can observe address(c).balance change
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // compute net change observed
        uint256 deltaC;
        if (afterC >= beforeC) {
            deltaC = afterC - beforeC;
        } else {
            // funds left c
            deltaC = 0; // represent as 0 when decreased; we will reason below using inequalities
        }

        // General invariant assertions expressed as one condition:
        // 1) If migrate was called and did not revert, then contract C's balance must have decreased (migrate transfers whole balance). Because only creator can call migrate, for our caller (not the creator) migrate should revert; so if it didn't revert, then address(c).balance must be zero after call and either beforeC was zero or funds moved out.
        // 2) withdraw can only succeed if withdrawAmount <= depositor's recorded balance; if it succeeded then afterThis >= beforeThis and afterC <= beforeC.
        // 3) refund if succeeded transfers at most what was in contract: afterC <= beforeC and afterThis >= beforeThis.
        // Combine these into a single assert that checks consistency between observed balances and revert flags.

        assert(
            // If migrate was invoked and did not revert, c's balance must be zero after (migrate transfers all funds away)
            (callMigrate && !migrateReverted ? afterC == 0 : true)
            // If withdraw succeeded then this contract's balance increased (we received Ether) or withdraw reverted
            && (!withdrawReverted ? afterThis > beforeThis : true)
            // If refund succeeded then this contract's balance increased (we received Ether) or refund reverted
            && (!(callRefund) || !refundReverted ? afterThis >= beforeThis : true)
            // In all cases, address(c).balance never became negative (always true by type) and if funds left c then beforeC > afterC
            && (afterC <= beforeC ? true : true)
        );
    }

    // accept Ether sent from c during withdraw/refund/migrate
    receive() external payable {
        receivedFromC += msg.value;
    }
}

contract InvMutTest {
    C c;
    uint256 public receivedFromC;

    constructor(C _c) {
        c = _c;
        receivedFromC = 0;
    }

    // single public test function
    function run(address to, uint256 depositAmount, uint256 withdrawAmount, bool doRefund, bool doMigrate) public payable {
        // ensure we have Ether to send for deposit if requested
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount);
        }

        // record before balances
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // perform deposit as a top-level call if requested
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // attempt withdraw as a top-level try/catch
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // attempt refund as a top-level try/catch if requested
        bool refundReverted = true;
        if (doRefund) {
            try c.refund() {
                refundReverted = false;
            } catch {
                refundReverted = true;
            }
        }

        // attempt migrate as a top-level try/catch if requested
        bool migrateReverted = true;
        if (doMigrate) {
            try c.migrateTo(to) {
                migrateReverted = false;
            } catch {
                migrateReverted = true;
            }
        }

        // read after balances
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // single assert stating the general rule
        // - If withdraw succeeded, this contract's balance increased and C's balance decreased by at least the amount received.
        // - If refund succeeded, this contract's balance increased and C's balance decreased by at least the amount received.
        // - If migrate succeeded, C's balance is zero afterwards.
        assert(
            (
                !withdrawReverted
                ? (afterThis >= beforeThis && afterC + (afterThis - beforeThis) <= beforeC + depositAmount)
                : true
            )
            && (
                (doRefund && !refundReverted)
