    function run(uint256 seedDeposit) public payable {
        require(address(this).balance >= seedDeposit, "insufficient balance to seed");

        // Seed a balance in c for this contract's address by calling deposit.
        // If deposit reverts due to overflow when seedDeposit == 0, that's okay; we still test refund behaviour.
        bool depositReverted;
        try c.deposit{value: seedDeposit}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // Observe c's total balance and this contract's reported balance-in-c for msg.sender before refund.
        uint256 cBalBefore = address(c).balance;
        // balances mapping is private in C, so we cannot read it directly. However, after deposit we can infer
        // that calling refund will transfer out at most cBalBefore and will set the caller's balance to zero as observable by subsequent refunds.

        // Call refund and record whether it reverted.
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        uint256 cBalAfter = address(c).balance;

        // General rule: refund should never increase the contract's total balance; and if it succeeds then
        // a subsequent refund must transfer zero (i.e., calling refund twice in a row cannot withdraw extra funds).
        // We express this by: either the first refund reverted, or cBalAfter <= cBalBefore, and if first refund succeeded
        // then a second refund must not change c's balance further (idempotence for caller's balance).

        if (!refundReverted) {
            // Call refund a second time and ensure c balance does not decrease further (i.e., caller's balance was zeroed).
            bool secondReverted;
            try c.refund() {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
            uint256 cBalAfterSecond = address(c).balance;

            // Assertion: first refund did not increase contract balance, and second refund did not decrease it further.
            assert(cBalAfter <= cBalBefore && cBalAfterSecond >= cBalAfter);
        } else {
            // If the first refund reverted, require that it did not violate the non-increase property (we cannot observe transfer on revert),
            // so only assert that the contract balance did not increase spontaneously.
            assert(cBalAfter <= cBalBefore);
        }
    }

    receive() external payable { }
}

