contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We drive c by optionally depositing some ether (so the withdraw may succeed) and then attempt a withdraw.
    // Parameters:
    // - depositAmount: amount to deposit into c before testing (this contract must hold at least that much)
    // - withdrawAmount: amount to attempt to withdraw from c
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // ensure this test contract has funds to deposit if requested
        require(address(this).balance >= depositAmount);

        // Optional deposit to give this contract a recorded balance inside c
        bool depReverted;
        try c.deposit{value: depositAmount}() {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        // Try to withdraw withdrawAmount. Record whether it reverted.
        bool wdReverted;
        try c.withdraw(withdrawAmount) {
            wdReverted = false;
        } catch {
            wdReverted = true;
        }

        // After the withdraw attempt, to observe the caller's remaining recorded balance we attempt a withdraw of 0.
        // If withdraw(0) reverts, we treat that as inability to observe; otherwise it must succeed and not change state.
        bool probeReverted;
        try c.withdraw(0) {
            probeReverted = false;
        } catch {
            probeReverted = true;
        }

        // The invariant we assert: if the earlier withdraw succeeded (wdReverted == false), then the probe withdraw(0) must NOT revert.
        // Intuition: withdraw succeeds only when amount <= balances[msg.sender]; after a successful withdraw the recorded balance remains >= 0
        // and withdraw(0) should still be allowed (it requires 0 <= balances[msg.sender], always true). If withdraw unexpectedly succeeded but
        // withdraw(0) now reverts, that would violate basic consistency of the withdraw precondition.
        assert(!(wdReverted == false) || (probeReverted == false));
    }

    // Allow the test contract to receive refunds/transfers from c during withdraw/refund/migrateTo
    receive() external payable {}
}

