    // We do not read msg.value; to send Ether we use depositAmount and c.deposit{value: depositAmount}().
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Optional deposit to create a nonzero recorded balance inside c for this caller
        bool depReverted;
        try c.deposit{value: depositAmount}() {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        // Record contract balance before refund and this test contract balance to observe transfers.
        uint256 cBalanceBefore = address(c).balance;
        uint256 selfBalanceBefore = address(this).balance;

        // Attempt refund and record whether it reverted.
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        uint256 cBalanceAfter = address(c).balance;
        uint256 selfBalanceAfter = address(this).balance;

        // To observe whether recorded balance was cleared when refund succeeded, try a probe withdraw(0).
        // If withdraw(0) reverts then probeReverted = true. If it succeeds, it should not transfer Ether (amount 0).
        bool probeReverted;
        try c.withdraw(0) {
            probeReverted = false;
        } catch {
            probeReverted = true;
        }

        // The invariant we assert:
        // If refund reverted, nothing is required about balances (we only assert the flag). If refund succeeded then:
        // 1) The Ether gained by this contract equals the decrease in c's balance: selfBalanceAfter - selfBalanceBefore == cBalanceBefore - cBalanceAfter.
        // 2) c's balance did not increase (i.e., cBalanceAfter <= cBalanceBefore).
        // 3) After a successful refund, the probe withdraw(0) must NOT revert (recorded balance for this caller is non-negative and withdraw(0) should be allowed).
        // Together these state observable properties express that refund transfers exactly the caller's recorded balance out and clears it.
        assert(refundReverted || ((selfBalanceAfter - selfBalanceBefore) == (cBalanceBefore - cBalanceAfter) && cBalanceAfter <= cBalanceBefore && probeReverted == false));
    }

    // Allow receiving Ether sent from c during refund/withdraw/migrateTo
    receive() external payable {}
}

